 if(!ready||connections.length!==7)return;phase='result';field.classList.add('frozen');let correct=0;connections.forEach(c=>{c.correct=c.left===c.right;if(c.correct)correct++;const l=$(`.match-brick[data-side="left"][data-id="${c.left}"]`),r=$(`.match-brick[data-side="right"][data-id="${c.right}"]`);l?.classList.add(c.correct?'correct':'incorrect');r?.classList.add(c.correct?'correct':'incorrect')});const score=matchingScore(correct);scores.push(score);results.push({code:'MAT',name:'CITY-COUNTRY',detail:`${correct}/7 answers correct`,score});setResult(`You got ${correct}/7 Answers Correct.`,`Correct pairs are green; incorrect pairs are red.`,score);sizeField();setStatus(`Scored / ${pad(score,3)}`,true);const btn=$('#actionBtn');btn.textContent='Continue';btn.disabled=false;updateRibbon();drawFx();
