/* ================= ESTIMATION ROUND ================= */
function dataExtent(key){const vals=DATA.map(c=>+c[key]).filter(Number.isFinite);return{min:Math.min(...vals),max:Math.max(...vals)}}
function sliderDef(){
 const pop=dataExtent('Population'),yr=dataExtent('Year Founded'),el=dataExtent('Elevation'),gd=dataExtent('GDP');
 const clamp01=p=>Math.max(0,Math.min(1,p));
 // Population: logarithmic. The 20k floor preserves useful low-end resolution without approaching log(0).
 const popMin=Math.min(20000,Math.max(1000,Math.floor(pop.min/1000)*1000)),popMax=Math.ceil(pop.max/100000)*100000,popLogSpan=Math.log(popMax/popMin);
 // Established year: square-root of age. Use the rounded newest year as the age-zero anchor so future/anomalous rows remain representable.
 const yearMin=Math.floor(yr.min/100)*100,yearMax=Math.ceil(yr.max/100)*100,yearAnchor=yearMax,yearAgeMax=Math.max(1,yearAnchor-yearMin),yearRootMax=Math.sqrt(yearAgeMax);
 // Elevation: square-root scale in feet, with a rounded floor that can represent below-sea-level cities.
 const elevRawMin=el.min*3.28084,elevRawMax=el.max*3.28084,elevMin=Math.floor(elevRawMin/100)*100,elevMax=Math.ceil(elevRawMax/1000)*1000,elevSpan=elevMax-elevMin;
 // GDP: logarithmic across the full positive dataset range.
 const gdPos=DATA.map(c=>+c.GDP).filter(v=>Number.isFinite(v)&&v>0),gdpDataMin=Math.min(...gdPos),gdpMin=Math.pow(10,Math.floor(Math.log10(gdpDataMin))),gdpMax=Math.ceil(gd.max/Math.pow(10,Math.max(0,Math.floor(Math.log10(gd.max))-1)))*Math.pow(10,Math.max(0,Math.floor(Math.log10(gd.max))-1)),gdpLogSpan=Math.log(gdpMax/gdpMin);
 const popTicks=[20000,100000,500000,1000000,5000000,10000000,25000000,50000000];
 const yearTicks=[-2500,-500,1000,1500,1800,1900,2000,2100];
 const elevTicks=[-100,0,500,1500,3000,6000,10000,15000];
 const gdpTicks=[1e6,3e6,1e7,3e7,1e8,3e8,1e9,3e9,1e10,3e10,1e11,3e11,1e12];
 return {
  population:{key:'Population',label:'Population',fmt:v=>popFmt(v).replace('Pop. ',''),toPos:v=>clamp01(Math.log(Math.max(popMin,v)/popMin)/popLogSpan),fromPos:p=>popMin*Math.exp(clamp01(p)*popLogSpan),ticks:popTicks.filter(v=>v>=popMin&&v<=popMax)},
  year:{key:'Year Founded',label:'Year Established',fmt:yearShort,toPos:v=>clamp01(1-Math.sqrt(Math.max(0,yearAnchor-v))/yearRootMax),fromPos:p=>yearAnchor-Math.pow((1-clamp01(p))*yearRootMax,2),ticks:yearTicks.filter(v=>v>=yearMin&&v<=yearMax)},
  elevation:{key:'Elevation',label:'Elevation',fmt:v=>`${Math.round(v).toLocaleString('en-US')} ft`,toPos:v=>clamp01(Math.sqrt(Math.max(0,(v-elevMin)/elevSpan))),fromPos:p=>elevMin+Math.pow(clamp01(p),2)*elevSpan,ticks:elevTicks.filter(v=>v>=elevMin&&v<=elevMax)},
  gdp:{key:'GDP',label:'GDP',fmt:moneyFmt,toPos:v=>clamp01(Math.log(Math.max(gdpMin,v)/gdpMin)/gdpLogSpan),fromPos:p=>gdpMin*Math.exp(clamp01(p)*gdpLogSpan),ticks:gdpTicks.filter(v=>v>=gdpMin&&v<=gdpMax)}
 };
}
function loadEstimateRound(){
 kind='estimation';setModeClass('estimation-mode');const city=pickEstimateCity(seeded('ESTIMATE_CITY')),defs=sliderDef();estimateState={city,defs,answers:{},scores:{}};setRoundHeader('EST','MULTI-METRIC','N / 01');$('#question').innerHTML=`${esc(city.City)}, ${esc(city.Country)}<small>Estimate all five values, then submit once</small>`;$('#topOrient').innerHTML='<span class="arrow">▲</span>Estimate / move each control';$('#bottomOrient').innerHTML='<span class="arrow">▼</span>Five components × 20 pts';$('#ruleTxt').textContent='5 estimates × 20 pts';setStatus('Adjust estimates',true);buildEstimateBoard();$('#actionBtn').disabled=false;ready=true;
}
function buildEstimateBoard(){
 const board=document.createElement('div');board.className='estimate-board';['population','year','elevation','gdp'].forEach(name=>board.appendChild(buildEstimateCard(name)));board.appendChild(buildLatitudeCard());field.appendChild(board);requestAnimationFrame(()=>{updateLatitudeVisual();sizeField()});
}
function initialEstimateValue(){return 500}
function actualFor(name){const c=estimateState.city;if(name==='population')return +c.Population;if(name==='year')return +c['Year Founded'];if(name==='elevation')return +c.Elevation*3.28084;if(name==='gdp')return +c.GDP;if(name==='latitude')return +c.Latitude;return 0}
function displayGuess(name,sliderValue){const d=estimateState.defs[name];return d.fmt(d.fromPos(+sliderValue/1000))}
function scaleTicksHTML(d){return `<div class="scale-ticks">${d.ticks.map(v=>`<span style="left:${(d.toPos(v)*100).toFixed(2)}%">${esc(d.fmt(v))}</span>`).join('')}</div>`}
function buildEstimateCard(name){
 const d=estimateState.defs[name],card=document.createElement('div');card.className='estimate-card';card.dataset.metric=name;card.innerHTML=`<div class="estimate-head"><span class="estimate-name">${esc(d.label)}</span><span class="estimate-value"></span></div><input class="estimate-range" type="range" min="0" max="1000" step="1" value="${initialEstimateValue()}">${scaleTicksHTML(d)}<div class="estimate-feedback"></div>`;const input=card.querySelector('input'),val=card.querySelector('.estimate-value');val.textContent=displayGuess(name,input.value);input.addEventListener('input',()=>{val.textContent=displayGuess(name,input.value)});return card;
}
function buildLatitudeCard(){
 const card=document.createElement('div');card.className='estimate-card latitude-card';card.dataset.metric='latitude';card.innerHTML=`<div class="estimate-head"><span class="estimate-name">Latitude</span><span class="estimate-value" id="latValue">0°</span></div><div class="latitude-wrap"><div class="lat-control"><input id="latSlider" class="lat-slider" type="range" min="-90" max="90" step="1" value="0"></div><div class="sphere" id="sphere"><canvas id="latitudeGradeCanvas" class="latitude-grade-canvas"></canvas><span class="lat-pole north">90° N</span><span class="lat-pole south">90° S</span><div id="latitudeRing" class="latitude-ring"></div><div id="latitudeAnswerRing" class="latitude-answer-ring hidden"></div></div></div><div class="range-ends"><span>90° S</span><span>Equator</span><span>90° N</span></div><div class="estimate-feedback"></div>`;card.querySelector('#latSlider').addEventListener('input',updateLatitudeVisual);return card;
}
function positionLatitudeRing(el,lat){const sphere=$('#sphere');if(!el||!sphere)return;const r=sphere.clientWidth/2-3,y=r-r*Math.sin(lat*Math.PI/180),w=Math.max(2,2*r*Math.cos(lat*Math.PI/180));el.style.top=`${y+3}px`;el.style.width=`${w}px`;el.style.height=`${Math.max(4,w*.13)}px`}
function updateLatitudeVisual(){const input=$('#latSlider'),ring=$('#latitudeRing');if(!input||!ring)return;const lat=+input.value;positionLatitudeRing(ring,lat);$('#latValue').textContent=`${Math.abs(lat)}° ${lat<0?'S':lat>0?'N':'Equator'}`}
function metricPositions(name){
 const card=$(`.estimate-card[data-metric="${name}"]`),input=card.querySelector('input'),raw=+input.value,actual=actualFor(name);
 if(name==='latitude')return{guess:raw,actual,guessPos:(raw+90)/180,answerPos:(actual+90)/180,guessText:`${Math.abs(raw)}° ${raw<0?'S':raw>0?'N':'Equator'}`,actualText:latFmt(actual).replace('Lat. ','')};
 const d=estimateState.defs[name],guessPos=raw/1000,guess=d.fromPos(guessPos);return{guess,actual,guessPos,answerPos:Math.max(0,Math.min(1,d.toPos(actual))),guessText:d.fmt(guess),actualText:d.fmt(actual)};
}
function bandColor(score){const miss=(100-score)/25;return gradBg(Math.min(4,miss))}
function scoringBandHTML(answerPos,guessPos){let cells='';for(let i=0;i<21;i++){const p=i/20,score=estimateBandScore(p,answerPos);cells+=`<i style="background:${bandColor(score)}"></i>`}return `<div class="score-band">${cells}<span class="guess-mark" style="left:calc(${(guessPos*100).toFixed(2)}% - 1px)"></span><span class="answer-mark" style="left:calc(${(answerPos*100).toFixed(2)}% - 2px)"></span></div><div class="score-band-key"><span>Your guess</span><span>Answer</span></div>`}
function gradeLatitudeSphere(answerPos){const sphere=$('#sphere'),canvas=$('#latitudeGradeCanvas'),answerRing=$('#latitudeAnswerRing');if(!sphere||!canvas||!answerRing)return;const w=sphere.clientWidth,h=sphere.clientHeight,d=Math.min(2,devicePixelRatio||1);canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);canvas.style.width=w+'px';canvas.style.height=h+'px';const x=canvas.getContext('2d');x.setTransform(d,0,0,d,0,0);x.clearRect(0,0,w,h);const r=Math.min(w,h)/2,cx=w/2,cy=h/2;x.globalAlpha=.72;for(let y=0;y<h;y++){const sy=(cy-(y+.5))/r;if(Math.abs(sy)>1)continue;const lat=Math.asin(Math.max(-1,Math.min(1,sy)))*180/Math.PI,p=(lat+90)/180,score=estimateBandScore(p,answerPos),half=Math.sqrt(Math.max(0,r*r-Math.pow(y+.5-cy,2)));x.fillStyle=bandColor(score);x.fillRect(cx-half,y,half*2,1)}x.globalAlpha=1;const actualLat=answerPos*180-90;positionLatitudeRing(answerRing,actualLat);answerRing.classList.remove('hidden')}
function submitEstimate(){
 let raw=0;['population','year','elevation','gdp','latitude'].forEach(name=>{const p=metricPositions(name),bandScore=estimateBandScore(p.guessPos,p.answerPos),pts=bandScore/5;estimateState.scores[name]=pts;raw+=pts;const card=$(`.estimate-card[data-metric="${name}"]`),input=card.querySelector('input');input.disabled=true;card.classList.add('graded');const visual=name==='latitude'?`<div class="latitude-grade-key">Sphere shading = score bands · blue = your guess · black = answer</div>`:scoringBandHTML(p.answerPos,p.guessPos);card.querySelector('.estimate-feedback').innerHTML=`<div class="feedback-row"><span>Answer: <b>${esc(p.actualText)}</b></span><span><b>${pts.toFixed(0)}/20</b></span></div>${visual}`;if(name==='latitude')gradeLatitudeSphere(p.answerPos)});
 const score=raw<=0?0:Math.min(100,Math.ceil(raw/10)*10);scores.push(score);results.push({code:'EST',name:'MULTI-METRIC',detail:`${raw.toFixed(0)}/100 raw · rounded up`,score});phase='result';setResult(`Composite estimation score: ${score}/100.`,`Raw component total ${raw.toFixed(0)}/100; round score rounded up to nearest 10.`,score);sizeField();gradeLatitudeSphere(metricPositions('latitude').answerPos);setStatus(`Scored / ${pad(score,3)}`,true);const btn=$('#actionBtn');btn.textContent='Continue';btn.disabled=false;updateRibbon();
}

/* ================= POINTER INPUT ================= */
window.addEventListener('pointermove',e=>{
 if($('#gameScreen').classList.contains('hidden'))return;const p=local(e);pointer=(p.x>=0&&p.y>=0&&p.x<=W&&p.y<=H)?p:null;
 if(kind==='ranking'&&drag){const b=drag.b,now=performance.now(),f=Math.max(1,(now-drag.t)/16.67),nx=Math.max(0,Math.min(W-b.w,p.x-drag.offX)),ny=Math.max(52,Math.min(H-b.h,p.y-drag.offY));b.vx=Math.max(-18,Math.min(18,(nx-b.x)/f));b.vy=Math.max(-18,Math.min(18,(ny-b.y)/f));b.x=nx;b.y=ny;drag.t=now;renderBrick(b)}
 if(kind==='matching'&&phase==='play'){
  if(cutting&&pointer)cutConnectionAtPoint(pointer);
  if(!matchDrag&&!cutting&&pointer){hoverConnection=-1;for(let i=0;i<connections.length;i++){const g=connectionGeom(connections[i]);if(g&&pointLineDistance(pointer,g)<=8){hoverConnection=i;break}}field.classList.toggle('cut-hover',hoverConnection>=0)}else field.classList.remove('cut-hover');
 }
 drawFx();
});
field.addEventListener('pointerdown',e=>{if(kind!=='matching'||phase!=='play'||matchDrag)return;if(e.target.closest('.match-node'))return;const p=local(e);let near=false;for(const c of connections){const g=connectionGeom(c);if(g&&pointLineDistance(p,g)<=9){near=true;break}}if(near){e.preventDefault();cutting=true;pointer=p;cutConnectionAtPoint(p)}});
window.addEventListener('pointerup',e=>{if(matchDrag)completeMatchDrag(e);if(cutting){cutting=false;field.classList.remove('cut-hover')}endBrickDrag()});
window.addEventListener('pointercancel',()=>{matchDrag=null;cutting=false;endBrickDrag();field.classList.remove('cut-hover')});
field.addEventListener('pointerleave',()=>{if(!drag&&!matchDrag&&!cutting)pointer=null;field.classList.remove('cut-hover')});

/* ================= ACTION / LOOP / END ================= */
function onAction(){
 if(phase==='result'){round++;if(round>=5)endGame();else loadRound();return}
 if(phase!=='play')return;if(kind==='ranking')submitRanking();else if(kind==='matching')submitMatching();else submitEstimate();
}
function loop(t){
 const dt=Math.min(2,(t-lastT)/16.67||1);lastT=t;
 if(kind==='ranking'&&phase==='play'&&!$('#gameScreen').classList.contains('hidden')){physicsStep(dt/2);physicsStep(dt/2);bricks.forEach(renderBrick);stableFrames=towerOK()?stableFrames+1:0;const nowReady=stableFrames>10;if(nowReady!==ready){ready=nowReady;$('#actionBtn').disabled=!ready;setStatus(ready?'Stack verified':'Awaiting stack',ready)}}
 if(phase!=='idle'&&!$('#gameScreen').classList.contains('hidden'))drawFx();requestAnimationFrame(loop);
}
function endGame(){
 phase='idle';show('#endScreen');updateRibbon();$('#seqTxt').textContent='05/05';const d=today.toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'});$('#endMode').innerHTML=`<span class="lbl">Mode</span>${gameMode==='daily'?'DAILY':'INFINITE'}`;$('#endDate').textContent=isoDate;$('#endTitle').textContent=`City Stack - ${gameMode==='daily'?'Daily':'Infinite'} Mode`;$('#endSubtitle').textContent=gameMode==='daily'?d:'Five-round city knowledge record';$('#ledgerBody').innerHTML=results.map((r,i)=>`<tr><td class="num">${i+1}.</td><td class="round-code">${esc(r.code||r.name)}</td><td class="emoji-score">${scoreBar(r.score)}</td><td class="r num">${r.score}</td></tr>`).join('');$('#totalVal').textContent=scores.reduce((a,b)=>a+b,0);$('#copied').textContent='';
}
function scoreText(){const d=today.toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}),lines=results.map((r,i)=>`${i+1}. ${r.code||r.name} / ${scoreBar(r.score)} ${r.score}`).join('\n'),total=scores.reduce((a,b)=>a+b,0),title=gameMode==='daily'?`City Stack - Daily Mode - ${d}:`:'City Stack - Infinite Mode:';return `${title}\n${lines}\nTOTAL: ${total}/500`}
async function copyScore(){const t=scoreText();try{await navigator.clipboard.writeText(t)}catch(e){const ta=document.createElement('textarea');ta.value=t;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}$('#copied').textContent='■ COPIED TO CLIPBOARD'}

$('#dailyBtn').onclick=()=>startGame('daily');$('#infiniteBtn').onclick=()=>startGame('infinite');$('#actionBtn').onclick=onAction;$('#copyBtn').onclick=copyScore;$('#restartBtn').onclick=()=>{scores=[];results=[];round=0;phase='idle';show('#startScreen');updateRibbon();drawStart()};
window.addEventListener('resize',()=>{if(!$('#startScreen').classList.contains('hidden'))drawStart();if(!$('#gameScreen').classList.contains('hidden')){sizeField();if(kind==='ranking'&&phase==='play'){const bw=brickW(),bh=brickH();bricks.forEach(b=>{b.w=bw;b.h=bh;b.el.style.width=bw+'px';b.el.style.height=bh+'px';b.x=Math.min(b.x,W-bw);b.y=Math.min(Math.max(52,b.y),H-b.h)})}if(kind==='estimation'){updateLatitudeVisual();if(phase==='result'){const p=metricPositions('latitude');gradeLatitudeSphere(p.answerPos)}}}});
updateRibbon();drawStart();requestAnimationFrame(loop);if(document.fonts)document.fonts.ready.then(drawStart);
